begin;
with j as (select * from jsonb_to_recordset($law7d0018$[{"code_id":"BK_RF","article_number":"8","version_date":"1998-07-31","article_text":"(Наименование в редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nК бюджетным полномочиям субъектов Российской Федерации относятся: (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nустановление порядка составления и рассмотрения проектов бюджета субъекта Российской Федерации и бюджетов территориальных государственных внебюджетных фондов,  утверждения и исполнения бюджета субъекта Российской Федерации и бюджетов территориальных государственных внебюджетных фондов,  осуществления контроля за их исполнением и утверждения отчета об исполнении бюджета субъекта Российской Федерации и бюджетов территориальных государственных внебюджетных фондов;\n\nсоставление и рассмотрение проектов бюджета субъекта Российской Федерации,  бюджетов территориальных государственных внебюджетных фондов,  утверждение и исполнение бюджета субъекта Российской Федерации и бюджетов территориальных государственных внебюджетных фондов,  осуществление контроля за их исполнением,  составление и утверждение отчетов об исполнении бюджета субъекта Российской Федерации и бюджетов территориальных государственных внебюджетных фондов,  составление отчетов об исполнении консолидированного бюджета субъекта Российской Федерации;\n\nустановление порядка представления в исполнительные органы субъектов Российской Федерации утвержденных местных бюджетов,  отчетов об исполнении местных бюджетов и иной бюджетной отчетности,  установленной федеральными органами государственной власти; (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nустановление и исполнение расходных обязательств субъекта Российской Федерации;\n\nопределение порядка установления и исполнения расходных обязательств муниципальных образований,  подлежащих исполнению за счет субвенций из бюджета субъекта Российской Федерации;\n\nустановление нормативов отчислений доходов в местные бюджеты от федеральных налогов и сборов,  в том числе от налогов,  предусмотренных специальными налоговыми режимами,  и (или)  региональных налогов,  подлежащих зачислению в соответствии с настоящим Кодексом и законодательством о налогах и сборах в бюджеты субъектов Российской Федерации; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nустановление нормативов отчислений доходов в бюджеты сельских поселений от федеральных налогов и сборов,  в том числе налогов,  предусмотренных специальными налоговыми режимами,  подлежащих зачислению в соответствии с настоящим Кодексом и законодательством Российской Федерации о налогах и сборах в бюджеты муниципальных районов,  в случае,  если законами субъекта Российской Федерации и принятыми в соответствии с ними уставом муниципального района и уставами сельских поселений за сельскими поселениями закреплены другие вопросы местного значения из числа вопросов местного значения городских поселений,  решаемых муниципальным районом на территориях сельских поселений; (Дополнение абзацем - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\nопределение законами субъектов Российской Федерации источников доходов бюджетов внутригородских районов,  за исключением случаев,  предусмотренных настоящим Кодексом; (Дополнение абзацем - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\nустановление порядка и условий предоставления межбюджетных трансфертов из бюджета субъекта Российской Федерации;\n\nпредоставление межбюджетных трансфертов из бюджета субъекта Российской Федерации;\n\nустановление общего порядка и условий предоставления межбюджетных трансфертов из местных бюджетов;\n\nосуществление государственных заимствований и предоставление государственных гарантий субъекта Российской Федерации,  предоставление бюджетных кредитов,  управление государственным долгом и государственными активами субъекта Российской Федерации; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nустановление,  детализация и определение порядка применения бюджетной классификации Российской Федерации в части,  относящейся к бюджету субъекта Российской Федерации и бюджетам территориальных государственных внебюджетных фондов; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nвременное осуществление отдельных бюджетных полномочий органов местного самоуправления;\n\nабзац; (Утратил силу - Федеральный закон от 26.07.2019 № 199-ФЗ)\n\nустановление нормативов отчислений доходов в местные бюджеты от отдельных неналоговых доходов,  подлежащих зачислению в бюджеты субъектов Российской Федерации; (Дополнение абзацем - Федеральный закон от 02.08.2019 № 307-ФЗ)\n\nиные бюджетные полномочия,  отнесенные настоящим Кодексом к бюджетным полномочиям органов государственной власти субъектов Российской Федерации. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nК бюджетным полномочиям субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя помимо вышеперечисленных бюджетных полномочий относятся: (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\nопределение законами указанных субъектов Российской Федерации источников доходов бюджетов внутригородских муниципальных образований городов федерального значения Москвы,  Санкт-Петербурга и Севастополя. Установленные настоящим Кодексом источники доходов местных бюджетов,  не отнесенные законами субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя к источникам доходов бюджетов внутригородских муниципальных образований,  зачисляются в бюджеты субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя; (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\nустановление нормативов отчислений доходов в бюджеты внутригородских муниципальных образований городов федерального значения Москвы,  Санкт-Петербурга и Севастополя от федеральных налогов и сборов,  в том числе от налогов,  предусмотренных специальными налоговыми режимами,  региональных налогов и (или)  местных налогов и сборов,  подлежащих зачислению в бюджеты субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя в соответствии с настоящим Кодексом и законодательством о налогах и сборах; (В редакции федеральных законов от 22.10.2014 № 311-ФЗ; от 03.11.2015 № 301-ФЗ)\n\nустановление нормативов отчислений доходов в бюджеты внутригородских муниципальных образований городов федерального значения Москвы,  Санкт-Петербурга и Севастополя от неналоговых доходов,  подлежащих зачислению в бюджеты субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя; (Дополнение абзацем - Федеральный закон от 02.08.2019 № 307-ФЗ)\n\nопределение объема и порядка предоставления межбюджетных трансфертов бюджетам внутригородских муниципальных образований субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя; (В редакции федеральных законов от 22.10.2014 № 311-ФЗ,  от 02.08.2019 № 307-ФЗ)\n\nопределение объема,  порядка предоставления и распределения дотаций на выравнивание бюджетной обеспеченности внутригородских муниципальных образований субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя; (Дополнение абзацем - Федеральный закон от 02.08.2019 № 307-ФЗ)\n\nопределение перечня и порядка исполнения расходных обязательств внутригородских муниципальных образований городов федерального значения Москвы,  Санкт-Петербурга и Севастополя,  вытекающих из полномочий по вопросам местного значения,  определенных законами субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя; (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\nопределение порядка ведения реестра расходных обязательств внутригородских муниципальных образований городов федерального значения Москвы,  Санкт-Петербурга и Севастополя. (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\n(Часть в редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nПоложения,  установленные настоящим Кодексом в отношении субъектов Российской Федерации (органов государственной власти субъектов Российской Федерации) ,  субъектов Российской Федерации - городов федерального значения (в части доходов их бюджетов) ,  бюджетов субъектов Российской Федерации и бюджетов территориальных фондов обязательного медицинского страхования,  распространяются на федеральные территории (органы публичной власти федеральных территорий) ,  за исключением положений,  устанавливающих полномочия субъектов Российской Федерации (органов государственной власти субъектов Российской Федерации) ,  субъектов Российской Федерации - городов федерального значения в отношении муниципальных образований (местных бюджетов) ,  находящихся на их территории. В случае,  если положения настоящего Кодекса содержат указание на закон субъекта Российской Федерации,  применяется нормативный правовой акт представительного органа федеральной территории. (Дополнение частью - Федеральный закон от 11.06.2021 № 195-ФЗ)  (В редакции Федерального закона от 29.11.2021 № 384-ФЗ)","article_title":"Статья 8. Бюджетные полномочия субъектов Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6005cf71b61bc42a76f2db42a0524361a8fe25df6568c97795c1fa6562f0a263"},{"code_id":"BK_RF","article_number":"80","version_date":"1998-07-31","article_text":"(Наименование в редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\n1. Предоставление бюджетных инвестиций юридическим лицам,  не являющимся государственными или муниципальными учреждениями и государственными или муниципальными унитарными предприятиями,  влечет возникновение права государственной или муниципальной собственности на эквивалентную часть уставных (складочных)  капиталов указанных юридических лиц,  которое оформляется участием Российской Федерации,  субъектов Российской Федерации и муниципальных образований в уставных (складочных)  капиталах таких юридических лиц в соответствии с гражданским законодательством Российской Федерации. Оформление доли Российской Федерации,  субъекта Российской Федерации,  муниципального образования в уставном (складочном)  капитале,  принадлежащей Российской Федерации,  субъекту Российской Федерации,  муниципальному образованию,  осуществляется в порядке и по ценам,  которые определяются в соответствии с законодательством Российской Федерации. (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\nПорядок принятия решений о предоставлении бюджетных инвестиций юридическим лицам,  не являющимся государственными или муниципальными учреждениями и государственными или муниципальными унитарными предприятиями,  из федерального бюджета,  бюджета субъекта Российской Федерации,  местного бюджета устанавливается соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией. (Дополнение абзацем - Федеральный закон от 27.12.2019 № 479-ФЗ)  (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nРешения о предоставлении бюджетных инвестиций юридическим лицам,  не являющимся государственными или муниципальными учреждениями и государственными или муниципальными унитарными предприятиями,  в объекты капитального строительства,  находящиеся в собственности указанных юридических лиц,  и (или)  на приобретение ими объектов недвижимого имущества либо в целях предоставления взноса в уставные (складочные)  капиталы дочерних обществ указанных юридических лиц на осуществление капитальных вложений в объекты капитального строительства,  находящиеся в собственности таких дочерних обществ,  и (или)  на приобретение такими дочерними обществами объектов недвижимого имущества из федерального бюджета,  бюджета субъекта Российской Федерации,  местного бюджета принимаются соответственно в форме правовых актов  Правительства  Российской Федерации,  высшего исполнительного органа субъекта Российской Федерации,  муниципальных правовых актов местной администрации муниципального образования. (Дополнение абзацем - Федеральный закон от 07.05.2013 № 104-ФЗ)  (В редакции федеральных законов от 28.12.2013 № 418-ФЗ,  от 18.07.2017 № 178-ФЗ,  от 27.12.2019 № 479-ФЗ,  от 29.11.2021 № 384-ФЗ,  от 14.04.2023 № 128-ФЗ)\n\nВ случае,  если подготовка обоснования инвестиций для объекта капитального строительства в соответствии с законодательством Российской Федерации является обязательной,  решения,  указанные в абзаце втором настоящего пункта,  в отношении таких объектов капитального строительства принимаются в том числе на основании подготовленного в установленном законодательством Российской Федерации порядке обоснования инвестиций и результатов его технологического и ценового аудита,  а также утвержденного задания на проектирование. (Дополнение абзацем - Федеральный закон от 19.07.2018 № 222-ФЗ)\n\n2. Бюджетные инвестиции из федерального бюджета,  планируемые к предоставлению юридическим лицам,  указанным в пункте 1 настоящей статьи,  утверждаются федеральным законом о федеральном бюджете в качестве отдельного приложения к данному федеральному закону с указанием юридического лица,  объема и цели предоставляемых бюджетных инвестиций,  за исключением бюджетных инвестиций,  источником финансового обеспечения которых являются бюджетные ассигнования резервных фондов Президента Российской Федерации и  Правительства  Российской Федерации,  а также бюджетных инвестиций,  предоставляемых в целях исполнения принятых в соответствии с федеральными законами решений об утвержденном размере капитала,  при внесении изменений в сводную бюджетную роспись в соответствии с абзацем двадцать первым пункта 7 статьи 217 настоящего Кодекса. (В редакции федеральных законов от 18.07.2017 № 178-ФЗ; от 28.11.2018 № 453-ФЗ)\n\n3. Договор между Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации или уполномоченными ими федеральными органами исполнительной власти,  исполнительными органами субъекта Российской Федерации,  а также местной администрацией муниципального образования и юридическим лицом,  указанным в пункте 1 настоящей статьи,  об участии соответственно Российской Федерации,  субъекта Российской Федерации или муниципального образования в собственности субъекта инвестиций оформляется в течение трех месяцев после дня вступления в силу закона (решения)  о бюджете. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nОбязательным условием,  включаемым в договоры о предоставлении бюджетных инвестиций юридическим лицам,  указанным в пункте 1 настоящей статьи,  является запрет приобретения за счет полученных средств иностранной валюты,  за исключением операций,  осуществляемых в соответствии с валютным законодательством Российской Федерации при закупке (поставке)  высокотехнологичного импортного оборудования,  сырья и комплектующих изделий,  а также связанных с достижением целей предоставления бюджетных инвестиций иных операций,  определенных решениями  Правительства  Российской Федерации,  высшего исполнительного органа субъекта Российской Федерации,  местной администрации муниципального образования,  в том числе указанными в абзаце втором пункта 1 настоящей статьи. (В редакции  федеральных законов от 18.07.2017 № 178-ФЗ,  от 14.04.2023 № 128-ФЗ)\n\nТребования к договорам,  заключенным в связи с предоставлением бюджетных инвестиций юридическим лицам,  указанным в пункте 1 настоящей статьи,  за счет средств федерального бюджета,  бюджета субъекта Российской Федерации,  местного бюджета,  устанавливаются соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией муниципального образования. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nОтсутствие оформленных в установленном порядке договоров служит основанием для непредоставления бюджетных инвестиций.\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 23-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 80. Предоставление бюджетных инвестиций юридическим лицам,  не являющимся государственными или муниципальными учреждениями и государственными или муниципальными унитарными предприятиями","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"61edb50fef2f1b5e07784e9531e1ff54c6207632b0bc1ea718713f986e8bcbed"},{"code_id":"BK_RF","article_number":"81","version_date":"1998-07-31","article_text":"1. В расходной части бюджетов бюджетной системы Российской Федерации (за исключением бюджетов государственных внебюджетных фондов)  предусматривается создание резервных фондов исполнительных органов государственной власти (местных администраций)  - резервного фонда  Правительства  Российской Федерации,  резервных фондов высших исполнительных органов субъектов Российской Федерации,  резервных фондов местных администраций. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\n2. В расходной части бюджетов бюджетной системы Российской Федерации запрещается создание резервных фондов законодательных (представительных)  органов и депутатов законодательных (представительных)  органов.\n\n3. Размер резервных фондов исполнительных органов государственной власти (местных администраций)  устанавливается законами (решениями)  о соответствующих бюджетах. (В редакции  Федерального закона от 21.11.2022 № 448-ФЗ)\n\n4. Средства резервных фондов исполнительных органов государственной власти (местных администраций)  направляются на финансовое обеспечение непредвиденных расходов,  в том числе на проведение аварийно-восстановительных работ и иных мероприятий,  связанных с ликвидацией последствий стихийных бедствий и других чрезвычайных ситуаций,  а также на иные мероприятия,  предусмотренные порядком,  указанным в пункте 6 настоящей статьи. (В редакции Федерального закона от 30.11.2016 № 409-ФЗ)\n\n5. Бюджетные ассигнования резервного фонда  Правительства  Российской Федерации,  резервного фонда высшего исполнительного органа субъекта Российской Федерации,  резервного фонда местной администрации,  предусмотренные в составе федерального\n\nразований. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nСоглашение о передаче полномочий может быть заключено в отношении нескольких объектов капитального строительства государственной (муниципальной)  собственности и (или)  объектов недвижимого имущества,  приобретаемых в государственную (муниципальную)  собственность,  и должно содержать в том числе:\n\nцель осуществления бюджетных инвестиций и их объем с разбивкой по годам в отношении каждого объекта капитального строительства или объекта недвижимого имущества с указанием его наименования,  мощности,  сроков строительства (реконструкции,  в том числе с элементами реставрации,  технического перевооружения)  или приобретения,  стоимости объекта,  соответствующих решениям,  указанным в пунктах 2 и 3 настоящей статьи,  а также общего объема капитальных вложений в объект государственной (муниципальной)  собственности,  в том числе объема бюджетных ассигнований,  предусмотренного соответствующему органу,  указанному в абзаце первом настоящего пункта,  как получателю бюджетных средств,  соответствующих решениям,  указанным в пунктах 2 и 3 настоящей статьи. В случае предоставления бюджетных инвестиций из федерального бюджета их объем должен соответствовать объему бюджетных ассигнований на осуществление бюджетных инвестиций,  определенному в соответствии со статьей 1791 настоящего Кодекса; (В редакции  Федерального закона от 25.12.2023 № 628-ФЗ)\n\nположения,  устанавливающие права и обязанности бюджетного или автономного учреждения,  государственного (муниципального)  унитарного предприятия по заключению и исполнению от имени соответствующего публично-правового образования в лице органа,  указанного в абзаце первом настоящего пункта,  государственных (муниципальных)  контрактов;\n\nответственность бюджетного или автономного учреждения,  государственного (муниципального)  унитарного предприятия за неисполнение или ненадлежащее исполнение переданных им полномочий;\n\nположения,  устанавливающие право органа,  указанного в абзаце первом настоящего пункта,  на проведение проверок соблюдения бюджетным или автономным учреждением,  государственным (муниципальным)  унитарным предприятием условий,  установленных заключенным соглашением о передаче полномочий;\n\nположения,  устанавливающие обязанность бюджетного или автономного учреждения,  государственного (муниципального)  унитарного предприятия по ведению бюджетного учета,  составлению и представлению бюджетной отчетности органу,  указанному в абзаце первом настоящего пункта,  как получателя бюджетных средств.\n\nСоглашения о передаче полномочий являются основанием для открытия органам,  указанным в абзаце первом настоящего пункта,  в органах Федерального казначейства (финансовых органах субъектов Российской Федерации и финансовых органах муниципальных образований)  лицевых счетов получателя бюджетных средств по переданным полномочиям для учета операций по осуществлению бюджетных инвестиций в объекты государственной (муниципальной)  собственности.\n\n41. В случаях,  определенных федеральными законами (за исключением федерального закона о федеральном бюджете) ,  иными нормативными правовыми актами о создании публично-правовых компаний,  государственным корпорациям (компаниям) ,  публично-правовым компаниям может предоставляться право на заключение и исполнение от имени Российской Федерации,  субъекта Российской Федерации государственных контрактов от лица органов государственной власти (государственных органов) ,  являющихся государственными заказчиками,  передавших государственным корпорациям (компаниям) ,  публично-правовым компаниям на безвозмездной основе на основании соглашений свои полномочия государственного заказчика при осуществлении бюджетных инвестиций в объекты капитального строительства (за исключением бюджетных инвестиций в целях реконструкции,  в том числе с элементами реставрации,  технического перевооружения указанных объектов) ,  которые будут находиться в государственной собственности,  в соответствии с решениями,  указанными в пунктах 2 и 3 настоящей статьи.\n\nСозданные в результате осуществления бюджетных инвестиций объекты капитального строительства,  указанные в абзаце первом настоящего пункта,  закрепляются в установленном порядке на праве оперативного управления за государственными учреждениями либо на праве оперативного управления или хозяйственного ведения за государственными унитарными предприятиями с последующим увеличением стоимости основных средств,  находящихся на праве оперативного управления у государственных учреждений либо на праве оперативного управления или хозяйственного ведения у государственных унитарных предприятий,  а также увеличением уставного фонда указанных предприятий,  основанных на праве хозяйственного ведения,  в соответствии с решениями,  указанными в пунктах 2 и 3 настоящей статьи.\n\nПолномочия государственного (муниципального)  заказчика могут быть переданы федеральными органами исполнительной власти,  исполнительными органами субъекта Российской Федерации,  органами местного самоуправления,  являющимися государственными (муниципальными)  заказчиками,  юридическим лицам,  акции (доли)  которых принадлежат соответственно Российской Федерации,  субъекту Российской Федерации,  муниципальному образованию,  при осуществлении бюджетных инвестиций в объекты капитального строительства государственной (муниципальной)  собственности с последующей передачей указанных объектов в качестве вклада в уставные (складочные)  капиталы таких юридических лиц в соответствии с решениями,  указанными в пунктах 2 и 3 настоящей статьи. Указанные решения должны содержать информацию о юридических лицах,  которым передаются полномочия государственного (муниципального)  заказчика. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nПередача объектов капитального строительства в качестве вклада в уставные (складочные)  капиталы юридических лиц,  указанных в абзаце третьем настоящего пункта,  влечет возникновение права государственной или муниципальной собственности на эквивалентную часть уставных (складочных)  капиталов указанных юридических лиц,  которое оформляется участием Российской Федерации,  субъектов Российской Федерации и муниципальных образований в уставных (складочных)  капиталах таких юридических лиц в соответствии с гражданским законодательством Российской Федерации. Оформление доли Российской Федерации,  субъекта Российской Федерации,  муниципального образования в уставном (складочном)  капитале,  принадлежащей Российской Федерации,  субъекту Российской Федерации,  муниципальному образованию,  осуществляется в порядке и по ценам,  которые определяются в соответствии с законодательством Российской Федерации.\n\nПри передаче государственным корпорациям (компаниям) ,  публично-правовым компаниям или иным юридическим лицам полномочий,  предусмотренных настоящим пунктом,  на них распространяются положения,  установленные пунктом 4 настоящей статьи для бюджетных и автономных учреждений,  государственных (муниципальных)  унитарных предприятий.\n\n(Дополнение пунктом - Федеральный закон от 18.07.2017 № 178-ФЗ)\n\n5. Бюджетные инвестиции в объекты капитального строительства государственной (муниципальной)  собственности могут осуществляться в соответствии с концессионными соглашениями.\n\n6. Не допускается при исполнении соответствующего бюджета предоставление бюджетных инвестиций в объекты государственной (муниципальной)  собственности,  по которым принято решение о предоставлении субсидий на осуществление капитальных вложений в объекты государственной (муниципальной)  собственности,  за исключением случая,  указанного в абзаце втором настоящего пункта. (В редакции Федерального закона от 29.12.2015 № 406-ФЗ)\n\nПри исполнении соответствующего бюджета допускается предоставление бюджетных инвестиций в объекты государственной (муниципальной)  собственности,  указанные в абзаце первом настоящего пункта,  в случае изменения в установленном порядке типа бюджетного или автономного учреждения или организационно-правовой формы государственного (муниципального)  унитарного предприятия,  являющихся получателями субсидий,  предусмотренных статьей 782 настоящего Кодекса,  на казенное учреждение после внесения соответствующих изменений в решение о предоставлении субсидий на осуществление капитальных вложений в указанные объекты с внесением соответствующих изменений в ранее заключенные бюджетным или автономным учреждением,  государственным (муниципальным)  унитарным предприятием договоры в части замены стороны договора - бюджетного или автономного учреждения,  государственного (муниципального)  унитарного предприятия на казенное учреждение и вида договора - гражданско-правового договора бюджетного или автономного учреждения,  государственного (муниципального)  унитарного предприятия на государственный (муниципальный)  контракт. (Дополнение абзацем - Федеральный закон от 29.12.2015 № 406-ФЗ)\n\n(Статья в редакции Федерального закона от 28.12.2013 № 418-ФЗ)","article_title":"Статья 81. Резервные фонды исполнительных органов государственной власти (местных администраций)","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9b5370a4ee5618af53e96837bd96487b4ad305cc1ad3d9b9c64272f6be613820"},{"code_id":"BK_RF","article_number":"81.1","version_date":"1998-07-31","article_text":"1. Законом субъекта Российской Федерации (за исключением закона субъекта Российской Федерации о бюджете субъекта Российской Федерации)  может быть предусмотрено создание Резервного фонда субъекта Российской Федерации.\n\nВ случае создания Резервного фонда субъекта Российской Федерации порядок формирования и использования средств указанного Фонда устанавливается законом субъекта Российской Федерации (за исключением закона субъекта Российской Федерации о бюджете субъекта Российской Федерации) .\n\n2. Резервный фонд субъекта Российской Федерации представляет собой часть средств бюджета субъекта Российской Федерации,  предназначенную для исполнения расходных обязательств субъекта Российской Федерации в случае недостаточности доходов бюджета субъекта Российской Федерации для финансового обеспечения расходных обязательств.\n\n(Дополнение статьей - Федеральный закон от 30.12.2008 № 310-ФЗ)","article_title":"Статья 81.1. Резервный фонд субъекта Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0019d7af3b97d2f5b219c4a26d3cf46a4e10fc990b31bc48eb717737f6ffc8c2"},{"code_id":"BK_RF","article_number":"82","version_date":"1998-07-31","article_text":"1. Федеральным бюджетом на очередной финансовый год и плановый период предусматривается создание резервного фонда Президента Российской Федерации в размере не более 1 процента утвержденных расходов федерального бюджета. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n2. Средства резервного фонда Президента Российской Федерации используются на финансовое обеспечение непредвиденных расходов. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n3. Использование бюджетных ассигнований резервного фонда Президента Российской Федерации осуществляется на основании указов и распоряжений Президента Российской Федерации. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n4. Использование бюджетных ассигнований резервного фонда Президента Российской Федерации на проведение выборов,  референдумов,  освещение деятельности Президента Российской Федерации не допускается. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 82. Резервный фонд Президента Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3d1aae30ca602184229d5b99df70d6673438af33990c1bc6ef7886f790f3743e"},{"code_id":"BK_RF","article_number":"83","version_date":"1998-07-31","article_text":"1. Если принимается закон либо другой нормативный правовой акт,  предусматривающий увеличение расходных обязательств по существующим видам расходных обязательств или введение новых видов расходных обязательств,  которые до его принятия не исполнялись ни одним публично-правовым образованием,  указанный нормативный правовой акт должен содержать нормы,  определяющие источники и порядок исполнения новых видов расходных обязательств,  в том числе в случае необходимости порядок передачи финансовых ресурсов на новые виды расходных обязательств в соответствующие бюджеты бюджетной системы Российской Федерации.\n\n2. Выделение бюджетных ассигнований на принятие новых видов расходных обязательств или увеличение бюджетных ассигнований на исполнение существующих видов расходных обязательств может осуществляться только с начала очередного финансового года при условии включения соответствующих бюджетных ассигнований в закон (решение)  о бюджете либо в текущем финансовом году после внесения соответствующих изменений в закон (решение)  о бюджете при наличии соответствующих источников дополнительных поступлений в бюджет и (или)  при сокращении бюджетных ассигнований по отдельным статьям расходов бюджета.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n(Наименование в редакции Федерального закона  от 26.04.2007 № 63-ФЗ)\n\n(Глава в редакции Федерального закона от 20.08.2004 № 120-ФЗ)","article_title":"Статья 83. Осуществление расходов,  не предусмотренных бюджетом","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fd26c08348b638cfdb983d663c276f5ac78ff85e2b9fe2f1c387105760793a19"},{"code_id":"BK_RF","article_number":"84","version_date":"1998-07-31","article_text":"1. Расходные обязательства Российской Федерации возникают в результате:\n\nпринятия федеральных законов и (или)  нормативных правовых актов Президента Российской Федерации и  Правительства  Российской Федерации при осуществлении федеральными органами государственной власти полномочий по предметам ведения Российской Федерации и (или)  полномочий по предметам совместного ведения,  не отнесенным в соответствии с Федеральным законом от 21 декабря 2021 года № 414-ФЗ \"Об общих принципах организации публичной власти в субъектах Российской Федерации\" к полномочиям органов государственной власти субъектов Российской Федерации; (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nзаключения Российской Федерацией (от имени Российской Федерации)  договоров (соглашений)  при осуществлении федеральными органами государственной власти полномочий по предметам ведения Российской Федерации и (или)  полномочий по предметам совместного ведения,  не отнесенным в соответствии с Федеральным законом от 21 декабря 2021 года № 414-ФЗ \"Об общих принципах организации публичной власти в субъектах Российской Федерации\" к полномочиям органов государственной власти субъектов Российской Федерации; (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nзаключения от имени Российской Федерации договоров (соглашений)  федеральными казенными учреждениями; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nпринятия федеральных законов и (или)  нормативных правовых актов Президента Российской Федерации и  Правительства  Российской Федерации,  предусматривающих предоставление из федерального бюджета межбюджетных трансфертов в формах и порядке,  предусмотренных настоящим Кодексом,  в том числе:\n\nсубвенций бюджетам субъектов Российской Федерации,  бюджетам территориальных фондов обязательного медицинского страхования на исполнение расходных обязательств субъектов Российской Федерации в связи с осуществлением органами государственной власти субъектов Российской Федерации переданных им отдельных государственных полномочий Российской Федерации; (В редакции Федерального закона от 29.11.2010 № 313-ФЗ)\n\nсубвенций бюджетам субъектов Российской Федерации для предоставления субвенций местным бюджетам на исполнение расходных обязательств муниципальных образований в связи с наделением органов местного самоуправления отдельными государственными полномочиями Российской Федерации.\n\n(Пункт в редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n2. Расходные обязательства Российской Федерации исполняются за счет собственных доходов и источников финансирования дефицита федерального бюджета. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nВ случаях,  установленных федеральными законами,  расходные обязательства Российской Федерации исполняются за счет средств бюджетов государственных внебюджетных фондов Российской Федерации. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n3. Положения федеральных законов и (или)  нормативных правовых актов Президента Российской Федерации и (или)  нормативных правовых актов  Правительства  Российской Федерации,  предусматривающие предоставление субвенций из федерального бюджета (бюджета Федерального фонда обязательного медицинского страхования)  бюджетам субъектов Российской Федерации (бюджетам территориальных фондов обязательного медицинского страхования) ,  должны содержать порядок расчета нормативов для определения общего объема субвенций на исполнение соответствующих расходных обязательств субъектов Российской Федерации (муниципальных образований) . (В редакции федеральных законов от 29.11.2010 № 313-ФЗ; от 07.05.2013 № 104-ФЗ)","article_title":"Статья 84. Расходные обязательства Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fe26edf365c37f0b7c5a3665c839df949c6b544813c802f736d28e81a7847cf3"},{"code_id":"BK_RF","article_number":"85","version_date":"1998-07-31","article_text":"1. Расходные обязательства субъекта Российской Федерации возникают в результате:\n\nпринятия законов и (или)  иных нормативных правовых актов субъекта Российской Федерации,  а также заключения субъектом Российской Федерации (от имени субъекта Российской Федерации)  договоров (соглашений)  при осуществлении органами государственной власти субъектов Российской Федерации полномочий по предметам ведения субъектов Российской Федерации,  в том числе соглашений о межрегиональном сотрудничестве для совместного развития инфраструктуры; (В редакции  Федерального закона от 28.12.2022 № 562-ФЗ)\n\nпринятия законов и (или)  иных нормативных правовых актов субъекта Российской Федерации,  а также заключения субъектом Российской Федерации (от имени субъекта Российской Федерации)  договоров (соглашений)  при осуществлении органами государственной власти субъектов Российской Федерации полномочий по предметам совместного ведения,  указанных в частях 1 и 5 статьи 44 Федерального закона от 21 декабря 2021 года № 414-ФЗ \"Об общих принципах организации публичной власти в субъектах Российской Федерации\"; (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nзаключения от имени субъекта Российской Федерации договоров (соглашений)  казенными учреждениями субъекта Российской Федерации; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nпринятия законов и (или)  иных нормативных правовых актов субъекта Российской Федерации,  предусматривающих предоставление из бюджета субъекта Российской Федерации межбюджетных трансфертов в формах и порядке,  предусмотренных настоящим Кодексом,  в том числе субвенций местным бюджетам на исполнение расходных обязательств муниципальных образований в связи с наделением органов местного самоуправления отдельными государственными полномочиями субъектов Российской Федерации;\n\nпринятия законов и (или)  иных нормативных правовых актов органов государственной власти субъектов Российской Федерации при осуществлении органами государственной власти субъектов Российской Федерации переданных им полномочий Российской Федерации.\n\n(Пункт в редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n2. Расходные обязательства субъекта Российской Федерации,  указанные в абзацах втором - пятом пункта 1 настоящей статьи,  устанавливаются органами государственной власти субъекта Российской Федерации самостоятельно и исполняются за счет собственных доходов и источников финансирования дефицита бюджета субъекта Российской Федерации. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nВ случаях,  установленных федеральными законами,  регулирующими деятельность территориальных государственных внебюджетных фондов,  и (или)  принимаемыми в соответствии с ними законами субъектов Российской Федерации,  расходные обязательства субъекта Российской Федерации могут исполняться за счет средств соответствующих бюджетов территориальных государственных внебюджетных фондов. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n3. Законы субъекта Российской Федерации,  предусматривающие предоставление местным бюджетам субвенций из бюджета субъекта Российской Федерации,  должны содержать порядок расчета нормативов для определения общего объема субвенций на исполнение соответствующих расходных обязательств муниципальных образований. (В редакции федеральных законов от 26.04.2007 № 63-ФЗ; от 07.05.2013 № 104-ФЗ)\n\n4. Расходные обязательства субъекта Российской Федерации,  указанные в абзаце шестом пункта 1 настоящей статьи,  устанавливаются законами и (или)  иными нормативными правовыми актами органов государственной власти субъекта Российской Федерации в соответствии с федеральными законами и (или)  нормативными правовыми актами Президента Российской Федерации и  Правительства  Российской Федерации и исполняются за счет и в пределах субвенций из федерального бюджета,  предоставляемых бюджетам субъектов Российской Федерации в порядке,  предусмотренном статьей 133 настоящего Кодекса,  а также за счет и в пределах субвенций из бюджета Федерального фонда обязательного медицинского страхования,  предоставляемых бюджетам территориальных фондов обязательного медицинского страхования в порядке,  предусмотренном статьей 1332 настоящего Кодекса. (В редакции Федерального закона от 29.11.2010 № 313-ФЗ)\n\nВ случае,  если в субъекте Российской Федерации превышены нормативы,  используемые в методиках расчета соответствующих субвенций,  финансовое обеспечение дополнительных расходов,  необходимых для полного исполнения указанных расходных обязательств субъекта Российской Федерации,  осуществляется за счет собственных доходов и источников финансирования дефицита бюджета субъекта Российской Федерации.\n\n(Пункт в редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n5. Органы государственной власти субъекта Российской Федерации самостоятельно определяют размеры и условия оплаты труда государственных гражданских служащих субъекта Российской Федерации и работников государственных учреждений субъекта Российской Федерации с соблюдением требований,  установленных настоящим Кодексом. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 26.04.2007 № 63-ФЗ)\n\n6. Органы государственной власти субъекта Российской Федерации не вправе устанавливать и исполнять расходные обязательства,  связанные с решением вопросов,  отнесенных к компетенции федеральных органов государственной власти,  за исключением случаев,  установленных федеральными законами.\n\nОрганы государственной власти субъекта Российской Федерации вправе устанавливать и исполнять расходные обязательства,  связанные с решением вопросов,  не отнесенных к компетенции федеральных органов государственной власти,  органов местного самоуправления и не исключенных из компетенции органов государственной власти субъекта Российской Федерации федеральными законами,  законами субъекта Российской Федерации,  только при наличии соответствующих средств бюджета субъекта Российской Федерации (за исключением межбюджетных трансфертов) . (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n7. Ежегодный объем расходов бюджета субъекта Российской Федерации,  являющегося в текущем финансовом году получателем дотаций на выравнивание бюджетной обеспеченности субъектов Российской Федерации,  направляемый на исполнение в очередном финансовом году и каждом году планового периода обязательств,  возникающих при исполнении концессионных соглашений (в размере платы концедента,  капитального гранта) ,  обязательств перед юридическими лицами,  являющимися стороной соглашений о государственно-частном партнерстве (в размере платы публичного партнера,  капитального гранта) ,  обязательств по уплате лизинговых платежей по договорам финансовой аренды (лизинга) ,  не должен превышать 10 процентов утвержденного общего годового объема доходов бюджета субъекта Российской Федерации без учета объема безвозмездных поступлений,  за исключением безвозмездных поступлений из федерального бюджета в целях софинансирования расходных обязательств субъектов Российской Федерации,  возникающих при исполнении указанных концессионных соглашений,  соглашений о государственно-частном партнерстве,  договоров финансовой аренды (лизинга) ,  а также безвозмездных поступлений от публично-правовой компании \"Фонд развития территорий\". (В редакции  Федерального закона от 21.04.2025 № 84-ФЗ)\n\nВ случае,  если в бюджете субъекта Российской Федерации,  являющегося в текущем финансовом году получателем дотаций на выравнивание бюджетной обеспеченности субъектов Российской Федерации,  на очередной финансовый год и плановый период объем расходов,  указанных в абзаце первом настоящего пункта,  превысил 10 процентов утвержденного общего годового объема доходов бюджета субъекта Российской Федерации без учета объема безвозмездных поступлений,  за исключением безвозмездных поступлений из федерального бюджета в целях софинансирования расходных обязательств субъектов Российской Федерации,  возникающих при исполнении указанных концессионных соглашений,  соглашений о государственно-частном партнерстве,  договоров финансовой аренды (лизинга) ,  а также безвозмездных поступлений от публично-правовой компании \"Фонд развития территорий\",  субъект Российской Федерации вправе осуществлять только принятые до 1 января очередного года обязательства,  возникшие при исполнении концессионных соглашений,  обязательства перед юридическими лицами,  являющимися стороной соглашений о государственно-частном партнерстве,  а также обязательства по уплате лизинговых платежей по договорам финансовой аренды (лизинга)  без принятия новых соответствующих обязательств.\n\nОграничение,  установленное абзацем первым настоящего пункта,  не распространяется на концессионные соглашения,  соглашения о государственно-частном партнерстве,  договоры финансовой аренды (лизинга) ,  заключенные до 1 января 2025 года. (В редакции  Федерального закона от 21.04.2025 № 84-ФЗ)\n\nОбъем расходов бюджета субъекта Российской Федерации,  являющегося в отчетном финансовом году получателем дотаций на выравнивание бюджетной обеспеченности субъектов Российской Федерации,  направленный на исполнение в отчетном финансовом году обязательств,  возникающих при исполнении концессионных соглашений (в размере платы концедента,  капитального гранта) ,  обязательств перед юридическими лицами,  являющимися стороной соглашений о государственно-частном партнерстве (в размере платы публичного партнера,  капитального гранта) ,  а также обязательств по уплате лизинговых платежей по договорам финансовой аренды (лизинга) ,  по данным годового отчета об исполнении бюджета субъекта Российской Федерации должен соответствовать ограничению,  установленному абзацем первым настоящего пункта. (В редакции  Федерального закона от 21.04.2025 № 84-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 13.07.2024 № 177-ФЗ)","article_title":"Статья 85. Расходные обязательства субъекта Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1c4abb188f9aa100a19aa434014123d3e521842f1e29b68eaba7ab1082892c00"},{"code_id":"BK_RF","article_number":"86","version_date":"1998-07-31","article_text":"1. Расходные обязательства муниципального образования возникают в результате:\n\nпринятия муниципальных правовых актов по вопросам местного значения и иным вопросам,  которые в соответствии с федеральными законами вправе решать органы местного самоуправления,  а также заключения муниципальным образованием (от имени муниципального образования)  договоров (соглашений)  по данным вопросам,  в том числе соглашений о межмуниципальном сотрудничестве для совместного развития инфраструктуры,  стороной которых является городской округ; (В редакции  федеральных законов от 26.04.2007 № 63-ФЗ,  от 28.12.2022 № 562-ФЗ)\n\nпринятия муниципальных правовых актов при осуществлении органами местного самоуправления переданных им отдельных государственных полномочий; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nзаключения от имени муниципального образования договоров (соглашений)  муниципальными казенными учреждениями. (Дополнение абзацем - Федеральный закон от 26.04.2007 № 63-ФЗ)  (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\n2. Расходные обязательства муниципального образования,  указанные в абзацах втором и четвертом пункта 1 настоящей статьи,  устанавливаются органами местного самоуправления самостоятельно и исполняются за счет собственных доходов и источников финансирования\n\nфонда  Правительства  Российской Федерации,  резервного фонда высшего исполнительного органа субъекта Российской Федерации,  резервного фонда местной администрации,  предусмотренные в составе федерального бюджета,  бюджета субъекта Российской Федерации,  местного бюджета,  используются по решению соответственно  Правительства  Российской Федерации,  высшего исполнительного органа субъекта Российской Федерации,  местной администрации. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\n6. Порядок использования бюджетных ассигнований резервного фонда  Правительства  Российской Федерации,  резервного фонда высшего исполнительного органа субъекта Российской Федерации,  резервного фонда местной администрации,  предусмотренных в составе федерального бюджета,  бюджета субъекта Российской Федерации,  местного бюджета,  устанавливается соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\n7. Отчет об использовании бюджетных ассигнований резервного фонда  Правительства  Российской Федерации прилагается к годовому отчету об исполнении федерального бюджета,  отчет об использовании бюджетных ассигнований резервных фондов высших исполнительных органов субъектов Российской Федерации,  резервных фондов местных администраций прилагается к годовому отчету об исполнении соответствующего бюджета. (В редакции  федеральных законов от 22.10.2014 № 311-ФЗ,  от 14.04.2023 № 128-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 86. Расходные обязательства муниципального образования","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"923334a0ab271ab2e5123725f355e5d7f177d9f497b436ebf7cbe7b9ef4c4911"},{"code_id":"BK_RF","article_number":"9","version_date":"1998-07-31","article_text":"(Наименование в редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n1. К бюджетным полномочиям муниципальных образований относятся: (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nустановление порядка составления и рассмотрения проекта местного бюджета,  утверждения и исполнения местного бюджета,  осуществления контроля за его исполнением и утверждения отчета об исполнении местного бюджета;\n\nсоставление и рассмотрение проекта местного бюджета,  утверждение и исполнение местного бюджета,  осуществление контроля за его исполнением,  составление и утверждение отчета об исполнении местного бюджета;\n\nустановление и исполнение расходных обязательств муниципального образования;\n\nопределение порядка предоставления межбюджетных трансфертов из местных бюджетов,  предоставление межбюджетных трансфертов из местных бюджетов;\n\nосуществление муниципальных заимствований,  предоставление муниципальных гарантий,  предоставление бюджетных кредитов,  управление муниципальным долгом и управление муниципальными активами; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nустановление,  детализация и определение порядка применения бюджетной классификации Российской Федерации в части,  относящейся к местному бюджету; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 26.07.2019 № 199-ФЗ)\n\nиные бюджетные полномочия,  отнесенные настоящим Кодексом к бюджетным полномочиям органов местного самоуправления. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n2. К бюджетным полномочиям муниципальных районов помимо полномочий,  перечисленных в пункте 1 настоящей статьи,  относятся: (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nустановление в соответствии с федеральными законами и законами субъектов Российской Федерации нормативов отчислений доходов в бюджеты городских,  сельских поселений от федеральных налогов и сборов,  в том числе от налогов,  предусмотренных специальными налоговыми режимами,  региональных и местных налогов,  подлежащих зачислению в соответствии с настоящим Кодексом,  законодательством о налогах и сборах и (или)  законами субъектов Российской Федерации в бюджеты муниципальных районов; (В редакции федеральных законов от 26.04.2007 № 63-ФЗ; от 29.11.2014 № 383-ФЗ)\n\nустановление в соответствии с федеральными законами и законами субъектов Российской Федерации нормативов отчислений доходов в бюджеты городских,  сельских поселений от отдельных неналоговых доходов,  подлежащих зачислению в бюджеты муниципальных районов; (Дополнение абзацем - Федеральный закон от 02.08.2019 № 307-ФЗ)\n\nустановление порядка и условий предоставления межбюджетных трансфертов из бюджета муниципального района бюджетам городских,  сельских поселений,  предоставление межбюджетных трансфертов из бюджета муниципального района бюджетам городских,  сельских поселений;\n\nабзац; (Утратил силу - Федеральный закон от 02.08.2019 № 307-ФЗ)\n\nсоставление отчета об исполнении консолидированного бюджета муниципального района.\n\n21. К бюджетным полномочиям городских округов с внутригородским делением помимо полномочий,  перечисленных в пункте 1 настоящей статьи,  относятся:\n\nустановление в соответствии с федеральными законами и законами субъектов Российской Федерации нормативов отчислений доходов в бюджеты внутригородских районов от федеральных налогов и сборов,  в том числе налогов,  предусмотренных специальными налоговыми режимами,  региональных и (или)  местных налогов,  подлежащих зачислению в соответствии с настоящим Кодексом,  законодательством Российской Федерации о налогах и сборах и (или)  законами субъектов Российской Федерации в бюджеты городских округов с внутригородским делением;\n\nустановление в соответствии с федеральными законами и законами субъектов Российской Федерации нормативов отчислений доходов в бюджеты внутригородских районов от отдельных неналоговых доходов,  подлежащих зачислению в бюджеты городских округов с внутригородским делением; (Дополнение абзацем - Федеральный закон от 02.08.2019 № 307-ФЗ)\n\nустановление порядка и условий предоставления межбюджетных трансфертов из бюджета городского округа с внутригородским делением бюджетам внутригородских районов,  предоставление межбюджетных трансфертов из бюджета городского округа с внутригородским делением бюджетам внутригородских районов;\n\nсоставление отчета об исполнении консолидированного бюджета городского округа с внутригородским делением.\n\n(Дополнение пунктом - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\n3. Органы местного самоуправления городских,  сельских поселений,  внутригородских районов,  муниципальных районов (в отношении населенных пунктов,  других территорий,  расположенных на межселенных территориях) ,  муниципальных округов,  городских округов,  внутригородских муниципальных образований городов федерального значения Москвы,  Санкт-Петербурга и Севастополя наряду с полномочиями,  перечисленными в пункте 1 настоящей статьи,  в соответствии с настоящим Кодексом осуществляют также бюджетные полномочия по установлению порядка составления,  утверждения и исполнения смет доходов и расходов отдельных населенных пунктов,  других территорий,  не являющихся муниципальными образованиями,  входящих в состав территории городского,  сельского поселения,  внутригородского района,  муниципального района (в отношении населенного пункта,  другой территории,  расположенных на межселенной территории) ,  муниципального округа,  городского округа,  внутригородского муниципального образования города федерального значения Москвы,  Санкт-Петербурга или Севастополя. (В редакции федеральных законов от 26.04.2007 № 63-ФЗ,  от 29.11.2014 № 383-ФЗ,  от 01.10.2020 № 311-ФЗ)\n\n4. (Дополнение пунктом - Федеральный закон от 26.04.2007 № 63-ФЗ)  (Утратил силу - Федеральный закон от 03.12.2012 № 244-ФЗ)\n\nЧАСТЬ ВТОРАЯ. БЮДЖЕТНАЯ СИСТЕМА РОССИЙСКОЙ ФЕДЕРАЦИИ","article_title":"Статья 9. Бюджетные полномочия муниципальных образований","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"889de84ccddf44420c7e2d672cd3bfe8fa677ccea4046204512d0631aa36c281"},{"code_id":"GK_RF","article_number":"1","version_date":"1994-11-30","article_text":"1. Гражданское законодательство основывается на признании равенства участников регулируемых им отношений, неприкосновенности собственности, свободы договора, недопустимости произвольного вмешательства кого-либо в частные дела, необходимости беспрепятственного осуществления гражданских прав, обеспечения восстановления нарушенных прав, их судебной защиты.\n\n2. Граждане (физические лица) и юридические лица приобретают и осуществляют свои гражданские права своей волей и в своем интересе. Они свободны в установлении своих прав и обязанностей на основе договора и в определении любых не противоречащих законодательству условий договора.\n\nГражданские права могут быть ограничены на основании федерального закона и только в той мере, в какой это необходимо в целях защиты основ конституционного строя, нравственности, здоровья, прав и законных интересов других лиц, обеспечения обороны страны и безопасности государства.\n\n3. При установлении, осуществлении и защите гражданских прав и при исполнении гражданских обязанностей участники гражданских правоотношений должны действовать добросовестно.\n\n4. Никто не вправе извлекать преимущество из своего незаконного или недобросовестного поведения.\n\n5. Товары, услуги и финансовые средства свободно перемещаются на всей территории Российской Федерации.\n\nОграничения перемещения товаров и услуг могут вводиться в соответствии с федеральным законом, если это необходимо для обеспечения безопасности, защиты жизни и здоровья людей, охраны природы и культурных ценностей.\n\n(Статья в редакции Федерального закона от 30.12.2012 № 302-ФЗ)","article_title":"Статья 1. Основные начала гражданского законодательства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"87cc5a719d9c13b3de94146528372d31d30c064c7c13c76ae26351f75030121d"},{"code_id":"GK_RF","article_number":"10","version_date":"1994-11-30","article_text":"1. Не допускаются осуществление гражданских прав исключительно с намерением причинить вред другому лицу, действия в обход закона с противоправной целью, а также иное заведомо недобросовестное осуществление гражданских прав (злоупотребление правом).\n\nНе допускается использование гражданских прав в целях ограничения конкуренции, а также злоупотребление доминирующим положением на рынке.\n\n2. В случае несоблюдения требований, предусмотренных пунктом 1 настоящей статьи, суд, арбитражный суд или третейский суд с учетом характера и последствий допущенного злоупотребления отказывает лицу в защите принадлежащего ему права полностью или частично, а также применяет иные меры, предусмотренные законом.\n\n3. В случае, если злоупотребление правом выражается в совершении действий в обход закона с противоправной целью, последствия, предусмотренные пунктом 2 настоящей статьи, применяются, поскольку иные последствия таких действий не установлены настоящим Кодексом.\n\n4. Если злоупотребление правом повлекло нарушение права другого лица, такое лицо вправе требовать возмещения причиненных этим убытков.\n\n5. Добросовестность участников гражданских правоотношений и разумность их действий предполагаются.\n\n(Статья в редакции Федерального закона от 30.12.2012 № 302-ФЗ)","article_title":"Статья 10. Пределы осуществления гражданских прав","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"82f26f8d6f4d34176e8729f9650f2d7524b5388c48b77d248e14119aa5800b86"},{"code_id":"GK_RF","article_number":"101","version_date":"1994-11-30","article_text":"Уменьшение уставного капитала общества допускается после уведомления всех его кредиторов в порядке, определяемом законом об акционерных обществах. Права кредиторов в случае уменьшения уставного капитала общества или снижения стоимости его чистых активов определяются законом об акционерных обществах. (В редакции Федерального закона от 27.12.2009 № 352-ФЗ)\n\nПрава и обязанности кредиторов кредитных организаций и некредитных финансовых организаций, созданных в организационно-правовой форме акционерного общества, определяются также законами, регулирующими деятельность таких организаций. (Дополнение абзацем - Федеральный закон от 08.07.1999 № 138-ФЗ) (В редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 101. Уменьшение уставного капитала акционерного общества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d7f6f6d368969fe29b3bb4aaf484728fdf195103c97fe8bb2fd9b6f6b54281b1"},{"code_id":"GK_RF","article_number":"102","version_date":"1994-11-30","article_text":"до полной оплаты всего уставного капитала;\n\nесли стоимость чистых активов акционерного общества меньше его уставного капитала и резервного фонда либо станет меньше их размера в результате выплаты дивидендов;\n\nв иных случаях, предусмотренных законом об акционерных обществах.  (Дополнение абзацем - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 102. Ограничения на выпуск ценных бумаг и выплату дивидендов акционерного общества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6d1dd038c10a736d04b6c9c2b48be5c9816c82b6d67a084a94d49ceefef4d2db"},{"code_id":"GK_RF","article_number":"103","version_date":"1994-11-30","article_text":"(Статья утратила силу - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 103. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"96fba3f60695998f879bdbc9750258cddcd5503f2d24a982065cb51d24eabbc0"},{"code_id":"GK_RF","article_number":"104","version_date":"1994-11-30","article_text":"1. Акционерное общество может быть реорганизовано или ликвидировано добровольно по решению общего собрания акционеров.\n\nИные основания и порядок реорганизации и ликвидации акционерного общества определяются законом. (В редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\n(Подпараграф утратил силу - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\n(Дополнение подпараграфом - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 104. Реорганизация и ликвидация акционерного общества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f2862a8eb72507cf5695b12bc5eaef2443cd7883117ac9a06301954fa97b9ad6"},{"code_id":"GK_RF","article_number":"106.1","version_date":"1994-11-30","article_text":"1. Производственным кооперативом (артелью) признается добровольное объединение граждан на основе членства для совместной производственной или иной хозяйственной деятельности (производство, переработка, сбыт промышленной, сельскохозяйственной и иной продукции, выполнение работ, торговля, бытовое обслуживание, оказание других услуг), основанной на их личном трудовом и ином участии и объединении его членами (участниками) имущественных паевых взносов. Законом и уставом производственного кооператива может быть предусмотрено участие в его деятельности юридических лиц. Производственный кооператив является корпоративной коммерческой организацией.\n\n2. Члены производственного кооператива несут по обязательствам кооператива субсидиарную ответственность в размерах и в порядке, которые предусмотрены законом о производственных кооперативах и уставом кооператива.","article_title":"Статья 106.1. Понятие производственного кооператива","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"13cefb020327b1f0a350aa89610e69e4f0d5e912228a0ed383e2751ce9446dd4"},{"code_id":"GK_RF","article_number":"106.2","version_date":"1994-11-30","article_text":"1. Учредительным документом производственного кооператива является его устав, утвержденный общим собранием его членов.\n\n2. Устав производственного кооператива должен содержать сведения о фирменном наименовании кооператива и месте его нахождения, условия о размере паевых взносов членов кооператива, составе и порядке внесения паевых взносов членами кооператива и об их ответственности за нарушение обязательства по внесению паевых взносов, о характере и порядке трудового участия его членов в деятельности кооператива и об их ответственности за нарушение обязанности принимать личное трудовое участие в деятельности кооператива, о порядке распределения прибыли и убытков кооператива, размере и об условиях субсидиарной ответственности его членов по обязательствам кооператива, о составе и компетенции органов кооператива и порядке принятия ими решений, в том числе по вопросам, решения по которым принимаются единогласно или квалифицированным большинством голосов.\n\n3. Фирменное наименование производственного кооператива должно содержать его наименование и слова \"производственный кооператив\" или слово \"артель\".\n\n4. Число членов кооператива не должно быть менее пяти.","article_title":"Статья 106.2. Создание производственного кооператива и его устав","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5cdaee1b3b4d4caf906a5219e6a9af51d6f882e121acaa625e2b9fc46c4c1f40"},{"code_id":"GK_RF","article_number":"106.3","version_date":"1994-11-30","article_text":"1. Имущество, находящееся в собственности производственного кооператива, делится на паи его членов в соответствии с уставом кооператива.\n\nУставом кооператива может быть установлено, что определенная часть принадлежащего кооперативу имущества составляет неделимые фонды, используемые на цели, определяемые уставом.\n\nРешение об образовании неделимых фондов принимается членами кооператива единогласно, если иное не предусмотрено уставом кооператива.\n\n2. Член производственного кооператива обязан внести к моменту регистрации кооператива не менее десяти процентов паевого взноса, а остальную часть в течение года с момента государственной регистрации кооператива.\n\n3. Прибыль производственного кооператива распределяется между его членами в соответствии с их трудовым участием, если иной порядок не предусмотрен законом о производственных кооперативах и уставом кооператива.\n\nВ таком же порядке распределяется имущество, оставшееся после ликвидации кооператива и удовлетворения требований его кредиторов.","article_title":"Статья 106.3. Имущество производственного кооператива","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e24ca2bc796d130af3e09d454d9d164e2ac49d2427557ef4a885d9b9f93eb080"},{"code_id":"GK_RF","article_number":"106.4","version_date":"1994-11-30","article_text":"1. Исполнительными органами производственного кооператива являются председатель и правление кооператива, если его образование предусмотрено законом или уставом кооператива.\n\n2. Членами правления производственного кооператива и председателем кооператива могут быть только члены кооператива.\n\n3. Член производственного кооператива имеет один голос при принятии решений общим собранием.","article_title":"Статья 106.4. Особенности управления в производственном кооперативе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8fabd1b5b4f2b12b192ffa19797b8eed1d548e51eabf6db9b3a02f9f7e1bee80"}]$law7d0018$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
